insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc6a4d99-9dc3-4483-b053-8182553c1e5c', 'es', '¿Cuál es la mejor mentalidad cuando hay una caída de energía en la conversación?', '["Verla como algo normal y reconducir con calma", "Tomarla como un fracaso y compensar de más", "Ignorarla y seguir con el mismo tema", "Terminar la interacción de inmediato"]'::jsonb, 'Mantenerte estable conserva tu aplomo y recupera el ritmo con naturalidad.')
