insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc8e3792-e6b6-47b1-b102-f1ec0d9d980b', 'es', 'Menciona un cambio de carrera. Tú también pasaste por uno. ¿Cuál es la mejor respuesta?', '["“Yo estoy pasando por lo mismo; es horrible”", "Ignorar su comentario y cambiar de tema", "“Yo también hice un cambio así; fue difícil, pero valió la pena”"]'::jsonb, 'Comparte algo ya procesado para identificarte con ella sin contar de más tu dolor.')
