insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fe98319f-7a07-4376-a92b-a4c12040ed64', 'es', '¿Por qué reconocer su respuesta crea seguridad psicológica?', '["Reconoce que sus experiencias importan", "Hace que se sienta entendida y se abra", "Te lleva rápido a la siguiente pregunta"]'::jsonb, 'Reconocer lo que dijo indica que sus palabras te llegaron y favorece un intercambio genuino.')
